#[cfg(test)]
mod order_cancel_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_order_cancel_codec() {
        let original = OrderCancel {
            biz_id: 123456,
            biz_pbu: "a".repeat(8),
            cl_ord_id: "a".repeat(10),
            security_id: "a".repeat(12),
            account: "a".repeat(13),
            owner_type: 42,
            side: "a".to_string(),
            orig_cl_ord_id: "a".repeat(10),
            transact_time: 123456789,
            branch_id: "a".repeat(8),
            user_info: "a".repeat(32),
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let mut bytes = buf.freeze();

        let decoded = OrderCancel::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
    }
}
